// Backend login route - make sure it returns a structure like this:
router.post("/login", async (req, res) => {
  try {
    const { user_id, password } = req.body;

    // Your existing login logic
    const userResult = await pool.query('SELECT * FROM users WHERE user_id = $1', [user_id]);
    
    if (userResult.rows.length === 0) {
      return res.status(400).json({ error: "Invalid credentials" });
    }

    const user = userResult.rows[0];
    // Compare password (make sure you're using bcrypt)
    const validPassword = await bcrypt.compare(password, user.password);
    
    if (!validPassword) {
      return res.status(400).json({ error: "Invalid credentials" });
    }

    // Generate JWT token
    const token = jwt.sign(
      { 
        user_id: user.user_id, 
        email: user.email,
        designation: user.designation 
      },
      process.env.JWT_SECRET,
      { expiresIn: '24h' }
    );

    // Return complete user data with token
    res.json({
      user_id: user.user_id,
      name: user.name,
      email: user.email,
      designation: user.designation,
      authtoken: token, // Make sure this is included
      // Include any other user fields you need
    });

  } catch (error) {
    console.error("Login error:", error);
    res.status(500).json({ error: "Server error" });
  }
});
